def infer_plant_part(row):
    latin_name = row.get("latin_name", "")
    if latin_name in SPECIAL_PLANT_PARTS:
        return SPECIAL_PLANT_PARTS[latin_name]
    for term, plant_part in PLANT_PART_TERMS:
        if term in latin_name:
            return plant_part
    english_name = row.get("english_name", "")
    if english_name in LOCAL_PLANT_PARTS:
        return LOCAL_PLANT_PARTS[english_name]
    name = english_name.lower()
    if "root" in name:
        return "Root"
    if "leaf" in name:
        return "Leaf"
    if "flower" in name or "blossom" in name:
        return "Flower"
    if "berry" in name or "fruit" in name:
        return "Fruit"
    return "Used material"


def infer_preparation(row):
    latin_name = row.get("latin_name", "")
    if "Recens" in latin_name:
        return "Fresh"
    if "Praeparata" in latin_name or "Praeparatum" in latin_name:
        return "Prepared"
    if latin_name in {"Natrii Sulfas", "Talcum"}:
        return "Prepared mineral"
    if latin_name in {"Fossilia Ossis Mastodi", "Haliotidis Concha", "Ostreae Concha"}:
        return "Prepared mineral/shell material"
    if row.get("item_type") == "local_plant":
        return "Fresh or dried"
    return "Dried"


def classify_material_note(row):
    plant_part = row["plant_part"].lower()
    preparation = row["preparation"].lower()
    if row.get("item_type") == "local_plant":
        return (
            f"This local row represents the {plant_part} in {preparation} form for "
            "TCM-style comparison. Other parts or preparations should be separate "
            "entries if their classification differs."
        )
    return (
        f"This entry represents the {plant_part} material in {preparation} form. "
        "Other plant parts or processing methods may have different TCM "
        "classifications."
    )


def add_preparation_modelling(rows):
    for row in rows:
        row.setdefault("plant_part", infer_plant_part(row))
        row.setdefault("preparation", infer_preparation(row))
        row.setdefault("classification_notes", classify_material_note(row))


