def build_additional_herb_media():
    media = {}
    for pinyin_name, subject, url, media_type in ADDITIONAL_HERB_MEDIA_ROWS:
        if media_type == "prepared":
            media[pinyin_name] = {
                "prepared_image_url": url,
                "prepared_image_caption": f"Representative image of {subject}.",
                "prepared_image_source_url": url,
            }
        else:
            media[pinyin_name] = {
                "plant_image_url": url,
                "plant_image_caption": f"Representative image of {subject}.",
                "plant_image_source_url": url,
            }
    return media


HERB_MEDIA.update(build_additional_herb_media())


