def build_local_plants():
    rows = []
    for (
        english_name,
        pinyin_name,
        latin_name,
        category,
        nature,
        flavors,
        meridians,
        ailments,
        local_habitat,
        substitution_notes,
        safety_notes,
    ) in LOCAL_PLANT_ROWS:
        row = {
                "english_name": english_name,
                "pinyin_name": pinyin_name,
                "pinyin_display": "" if pinyin_name == english_name else pinyin_name,
                "traditional_chinese_name": "",
                "simplified_chinese_name": "",
                "latin_name": latin_name,
                "category": category,
                "nature": nature,
                "flavors": flavors,
                "meridians": meridians,
                "ailments": ailments,
                "traditional_uses": substitution_notes,
                "safety_notes": safety_notes,
                "uk_growing": "hardy_outdoors",
                "uk_growing_notes": "Commonly found or readily grown outdoors in the UK. Harvest only where identification is certain and the site is clean and legal to forage.",
                "is_local_uk_plant": True,
                "is_british_herbalist_plant": english_name
                in BRITISH_HERBALIST_LOCAL_PLANTS,
                "item_type": "local_plant",
                "local_habitat": local_habitat,
                "substitution_notes": substitution_notes,
                "source_note": "Starter local-plant data using provisional TCM-style mapping from common Western herbal descriptions and known TCM overlaps. Verify clinically before using for substitution.",
            }
        row.update(LOCAL_PLANT_OVERRIDES.get(english_name, {}))
        image_url, image_caption, image_source_url = LOCAL_PLANT_MEDIA.get(
            english_name, ("", "", "")
        )
        if image_url:
            row.update(
                {
                    "plant_image_url": image_url,
                    "plant_image_caption": image_caption,
                    "plant_image_source_url": image_source_url,
                }
            )
        rows.append(row)
    return rows


HERBS.extend(build_local_plants())


add_preparation_modelling(HERBS)


