def build_culinary_spices():
    rows = []
    for (
        english_name,
        latin_name,
        category,
        nature,
        flavors,
        meridians,
        ailments,
        traditional_uses,
        safety_notes,
        substitution_notes,
        plant_image_url,
    ) in CULINARY_SPICE_ROWS:
        rows.append(
            {
                "english_name": english_name,
                "latin_name": latin_name,
                "item_type": "other_food",
                "category": category,
                "nature": nature,
                "flavors": flavors,
                "meridians": meridians,
                "ailments": ailments,
                "traditional_uses": traditional_uses,
                "safety_notes": safety_notes,
                "uk_growing": "not_practical",
                "uk_growing_notes": "Recorded as a kitchen spice or culinary herb; UK cultivation varies by species and is secondary to its role as a sourced seasoning.",
                "substitution_notes": substitution_notes,
                "plant_image_url": plant_image_url,
                "pinyin_name": english_name,
                "pinyin_display": english_name,
                "plant_image_caption": f"Representative image of {english_name}.",
                "plant_image_source_url": plant_image_url,
                "source_note": "Starter culinary herb and spice data using broad TCM-style food-therapy classifications. Culinary dose, preparation, and constitution matter.",
            }
        )
    return rows


def build_foods():
    keys = [
        "english_name",
        "latin_name",
        "item_type",
        "category",
        "nature",
        "flavors",
        "meridians",
        "ailments",
        "traditional_uses",
        "safety_notes",
        "uk_growing",
        "uk_growing_notes",
        "substitution_notes",
        "plant_image_url",
    ]
    rows = []
    for row in FOOD_ROWS:
        data = dict(zip(keys, row))
        data.update(
            {
                "pinyin_name": data["english_name"],
                "pinyin_display": data["english_name"],
                "plant_image_caption": f"Representative image of {data['english_name']}.",
                "plant_image_source_url": data["plant_image_url"],
                "source_note": "Starter food-therapy data using broad TCM dietary classifications from common educational references. Food responses vary by constitution, preparation, and portion.",
            }
        )
        rows.append(data)
    return rows


HERBS.extend(build_foods())
HERBS.extend(build_culinary_spices())


