def _append_unique_ingredients(ingredients, additions, default_importance="supporting"):
    seen = {row[0] for row in ingredients}
    enriched = list(ingredients)
    for ingredient in _normalize_recipe_ingredients(additions, default_importance):
        ingredient_name = ingredient[0]
        if ingredient_name not in seen:
            enriched.append(ingredient)
            seen.add(ingredient_name)
    return enriched


def _ingredient_importance(ingredient_name, default="primary"):
    if ingredient_name in CULINARY_SUPPORT_INGREDIENTS | PLAIN_CULINARY_INGREDIENTS:
        return "culinary"
    return default


def _normalize_recipe_ingredients(ingredients, default_importance="primary"):
    normalized = []
    for row in ingredients:
        if len(row) == 4:
            normalized.append(row)
            continue
        ingredient_name, amount, role = row
        normalized.append(
            (
                ingredient_name,
                amount,
                role,
                _ingredient_importance(ingredient_name, default_importance),
            )
        )
    return normalized


def _generic_recipe_supports(recipe):
    name = recipe["name"]
    category = recipe["category"].lower()

    if any(word in name for word in ["Tea", "Drink", "Water"]):
        return [
            ("Water", "500 ml", "Infusion or simmering medium"),
            ("Honey", "Optional", "Softens flavour"),
            ("Lemon", "Optional squeeze", "Sour fluid support"),
        ]

    if any(word in name for word in ["Compote", "Steamed Pear"]):
        return [
            ("Water", "2 tbsp", "Gentle cooking medium"),
            ("Honey", "1 tsp", "Moistening sweetener"),
            ("Sheng Jiang", "1 slice", "Warms and harmonizes"),
        ]

    if "Salad" in name or "Bowl" in name:
        return [
            ("Rice vinegar", "1 tbsp", "Sour dressing"),
            ("Sesame oil", "1 tsp", "Moistening finish"),
            ("Sea salt", "Pinch", "Seasoning"),
            ("Toasted seeds", "1 tbsp", "Texture garnish", "culinary"),
        ]

    if any(word in name for word in ["Stir-Fry", "Rice Bowl"]):
        return [
            ("Cooking oil", "1 tbsp", "Cooking medium", "culinary"),
            ("Soy sauce", "1 tbsp", "Salty savoury seasoning"),
            ("Sesame oil", "1 tsp", "Moistening finish"),
            ("Spring onion", "1", "Aromatic garnish"),
        ]

    if any(word in name for word in ["Soup", "Stew", "Broth"]):
        supports = [
            ("Vegetable stock", "750 ml", "Cooking base"),
            ("Sea salt", "Pinch", "Seasoning"),
        ]
        if "Stew" in name:
            supports.extend(
                [
                    ("Cooking oil", "1 tbsp", "Browning or softening medium", "culinary"),
                    ("Bay leaf", "1", "Slow-cooked aromatic", "culinary"),
                    ("Black pepper", "Optional pinch", "Finishing seasoning", "culinary"),
                ]
            )
        elif "clear heat" not in category and "cooling" not in category:
            supports.append(
                ("White pepper", "Optional pinch", "Finishing seasoning", "culinary")
            )
        if "clear heat" not in category and "cooling" not in category:
            supports.append(("Sheng Jiang", "2 slices", "Warms and harmonizes"))
        if "phlegm" in category or "food stagnation" in category:
            supports.append(("Chen Pi", "2 g", "Moves qi and transforms phlegm"))
        return supports

    if any(word in name for word in ["Congee", "Porridge", "Oats"]):
        return [
            ("Water", "4-6 cups", "Porridge cooking medium"),
            ("Da Zao", "2 dates", "Sweet harmonizer"),
            ("Honey", "Optional", "Sweetener"),
        ]

    return [
        ("Sea salt", "Pinch", "Seasoning"),
    ]


def _recipe_source_note(recipe):
    if recipe["name"] in CLASSICAL_FOOD_THERAPY_RECIPES:
        return CLASSICAL_RECIPE_NOTE
    if "Modern" in recipe["traditional_uses"] or "UK-friendly" in recipe["traditional_uses"]:
        return MODERN_RECIPE_NOTE
    return TRADITIONAL_STYLE_RECIPE_NOTE


def _display_ingredient_name(ingredient_name):
    for herb in HERBS:
        if herb["pinyin_name"] == ingredient_name:
            return herb["english_name"]
    return ingredient_name


def _ingredient_display_names(ingredients, importances=None):
    names = []
    for ingredient_name, _amount, _role, tcm_importance in ingredients:
        if importances and tcm_importance not in importances:
            continue
        names.append(_display_ingredient_name(ingredient_name))
    return names


def _join_ingredient_names(names):
    if not names:
        return "the prepared ingredients"
    if len(names) == 1:
        return names[0]
    if len(names) == 2:
        return f"{names[0]} and {names[1]}"
    return ", ".join(names[:-1]) + f", and {names[-1]}"


def _names_from_ingredients(ingredients, ingredient_names):
    selected_names = []
    for ingredient_name, _amount, _role, _tcm_importance in ingredients:
        if ingredient_name in ingredient_names:
            selected_names.append(_display_ingredient_name(ingredient_name))
    return selected_names


def _recipe_step_method(recipe, ingredients):
    name = recipe["name"]
    if name in SPECIFIC_RECIPE_STEPS:
        return SPECIFIC_RECIPE_STEPS[name]

    pattern_names = _ingredient_display_names(
        ingredients, {"primary", "supporting"}
    )
    culinary_names = _ingredient_display_names(ingredients, {"culinary"})
    pattern_text = _join_ingredient_names(pattern_names)
    culinary_text = _join_ingredient_names(culinary_names)

    if any(word in name for word in ["Tea", "Drink", "Water", "Syrup"]):
        return [
            f"Prepare {pattern_text} and place them in a small pan, jug, or teapot.",
            f"Add {culinary_text} and steep or simmer gently until the flavour enters the liquid.",
            "Strain if needed, then add any honey, lemon, or delicate aromatics after the liquid has cooled slightly.",
            "Serve warm or at room temperature according to season and constitution.",
        ]

    if any(word in name for word in ["Compote", "Steamed Pear"]):
        return [
            f"Prepare {pattern_text} by coring, slicing, or chopping larger pieces evenly.",
            f"Cook gently with {culinary_text} until the fruit softens.",
            "Keep the syrup light rather than heavily reduced, so the dish stays moistening.",
            "Serve warm for cold digestion or cooled for a more refreshing effect.",
        ]

    if any(word in name for word in ["Congee", "Porridge", "Oats"]):
        return [
            f"Prepare {pattern_text}, rinsing grains, seeds, or dried ingredients where needed.",
            f"Simmer with {culinary_text} until the grain or base ingredient softens into a porridge.",
            "Add any quick-cooking or finishing ingredients from this recipe near the end.",
            "Adjust thickness with hot water and serve warm, especially when supporting spleen-stomach digestion.",
        ]

    if any(word in name for word in ["Salad", "Bowl"]):
        return [
            f"Prepare {pattern_text}, cooking any grain, protein, or bean component first if needed.",
            "Slice the fresh ingredients finely enough that the dressing coats them evenly.",
            f"Dress with {culinary_text} just before serving.",
            "Serve at room temperature rather than ice-cold if digestion is weak.",
        ]

    if any(word in name for word in ["Stir-Fry", "Rice Bowl"]):
        return [
            f"Prepare {pattern_text} before heating the pan, because the cooking should be quick.",
            "Cook aromatics first, then add the denser or protein-rich ingredients and stir-fry until nearly done.",
            "Add any quick-cooking ingredients from this recipe last so they keep texture and colour.",
            f"Season and finish with {culinary_text}, then serve immediately.",
        ]

    if "Stew" in name:
        return [
            f"Brown or gently seal the main ingredients where appropriate: {pattern_text}.",
            f"Add {culinary_text} and bring the stew to a gentle simmer.",
            "Simmer slowly until the ingredients are tender and the broth has body.",
            "Season lightly at the end and serve warm in moderate portions.",
        ]

    if any(word in name for word in ["Soup", "Broth"]):
        delicate_names = _names_from_ingredients(
            ingredients,
            {
                "Tofu",
                "White fish",
                "Prawn",
                "Spinach",
                "Lettuce",
                "Watercress",
                "Rocket",
                "Pak choi",
                "Swiss chard",
                "Garden cress",
                "Coriander leaf",
                "Parsley",
                "Dill",
                "Bo He",
            },
        )
        if delicate_names:
            pronoun = "it does not" if len(delicate_names) == 1 else "they do not"
            final_addition_step = (
                f"Add {_join_ingredient_names(delicate_names)} near the end so "
                f"{pronoun} overcook."
            )
        else:
            final_addition_step = (
                "Simmer gently until the listed ingredients are tender and the "
                "broth has taken on their flavour."
            )
        cooking_medium_names = _names_from_ingredients(
            ingredients, {"Vegetable stock", "Water"}
        )
        cooking_medium_text = _join_ingredient_names(cooking_medium_names)
        seasoning_names = _names_from_ingredients(
            ingredients, {"Sea salt", "Soy sauce", "Sesame oil", "Rice vinegar"}
        )
        if seasoning_names:
            seasoning_step = (
                f"Season lightly with {_join_ingredient_names(seasoning_names)}, "
                "remove any fibrous medicinal slices if needed, and serve warm."
            )
        else:
            seasoning_step = (
                "Remove any fibrous medicinal slices if needed and serve warm."
            )
        return [
            f"Prepare {pattern_text} so each ingredient is ready before the broth starts.",
            f"Warm {cooking_medium_text}, then add the listed ingredients in the order needed for even cooking.",
            final_addition_step,
            seasoning_step,
        ]

    return [
        "Prepare the ingredients into even pieces.",
        "Cook gently using the preparation notes as the guide.",
        "Season lightly and serve in a way that fits the intended TCM pattern.",
    ]


def build_food_recipe_rows():
    rows = []
    for recipe in FOOD_RECIPE_ROWS:
        data = recipe.copy()
        ingredients = _normalize_recipe_ingredients(data["ingredients"], "primary")
        ingredients = _append_unique_ingredients(
            ingredients, SPECIFIC_RECIPE_SUPPORTS.get(data["name"], [])
        )
        ingredients = _append_unique_ingredients(
            ingredients, _generic_recipe_supports(data)
        )
        data["ingredients"] = ingredients
        data["source_note"] = _recipe_source_note(data)
        data["steps"] = _recipe_step_method(data, ingredients)
        rows.append(data)
    return rows


