class Command(BaseCommand):
    help = "Seed the database with starter Chinese herb, food, formula, and recipe records."

    def handle(self, *args, **options):
        categories = {}
        for name, description in CATEGORY_DESCRIPTIONS.items():
            categories[name], _ = HerbCategory.objects.update_or_create(
                name=name, defaults={"description": description}
            )

        for name, notes in AILMENT_NOTES.items():
            Ailment.objects.update_or_create(name=name, defaults={"notes": notes})

        if not Herb.objects.filter(
            pinyin_name="Xuan Shen",
            latin_name="Scrophularia nodosa",
            item_type="local_plant",
        ).exists():
            Herb.objects.filter(
                pinyin_name="Figwort",
                latin_name="Scrophularia nodosa",
                item_type="local_plant",
            ).update(pinyin_name="Xuan Shen")

        created_or_updated = 0
        for herb_data in HERBS:
            data = herb_data.copy()
            ailment_names = data.pop("ailments")
            category_name = data.pop("category")
            source_note = data.pop(
                "source_note",
                "Starter educational data summarising common TCM materia medica descriptions. Verify against qualified clinical references before use.",
            )
            media_data = HERB_MEDIA.get(data["pinyin_name"], {})
            herb, _ = Herb.objects.update_or_create(
                pinyin_name=data["pinyin_name"],
                latin_name=data["latin_name"],
                defaults={
                    **data,
                    **media_data,
                    "category": categories[category_name],
                    "source_note": source_note,
                },
            )
            ailment_objects = [
                Ailment.objects.get_or_create(
                    name=name, defaults={"notes": AILMENT_NOTES.get(name, "")}
                )[0]
                for name in ailment_names
            ]
            herb.ailments.set(ailment_objects)
            created_or_updated += 1

        formulas_created_or_updated = 0
        for formula_data in FORMULAS:
            data = formula_data.copy()
            ingredient_names = data.pop("ingredients")
            ailment_names = data.pop("ailments")
            formula, _ = Formula.objects.update_or_create(
                pinyin_name=data["pinyin_name"],
                traditional_chinese_name=data["traditional_chinese_name"],
                defaults={
                    **data,
                    "source_note": "Starter educational formula data summarising common TCM pattern associations. Formula composition can vary by lineage, manufacturer, and clinical modification.",
                },
            )
            formula_ailments = [
                Ailment.objects.get_or_create(
                    name=name, defaults={"notes": AILMENT_NOTES.get(name, "")}
                )[0]
                for name in ailment_names
            ]
            formula.ailments.set(formula_ailments)

            seen_ingredients = []
            for order, pinyin_name in enumerate(ingredient_names, start=1):
                herb = Herb.objects.get(pinyin_name=pinyin_name)
                FormulaIngredient.objects.update_or_create(
                    formula=formula,
                    herb=herb,
                    defaults={"order": order},
                )
                seen_ingredients.append(herb.pk)
            formula.ingredients.exclude(herb_id__in=seen_ingredients).delete()
            formulas_created_or_updated += 1

        recipes_created_or_updated = 0
        for recipe_data in build_food_recipe_rows():
            data = recipe_data.copy()
            ingredient_rows = data.pop("ingredients")
            step_rows = data.pop("steps")
            ailment_names = data.pop("ailments")
            source_note = data.pop(
                "source_note",
                "Starter educational food-therapy recipe data. Classifications are broad TCM-style dietary associations and should be adapted to constitution, season, preparation, and clinical context.",
            )
            recipe, _ = FoodRecipe.objects.update_or_create(
                name=data["name"],
                chinese_name=data["chinese_name"],
                defaults={
                    **data,
                    "source_note": source_note,
                },
            )
            recipe_ailments = [
                Ailment.objects.get_or_create(
                    name=name, defaults={"notes": AILMENT_NOTES.get(name, "")}
                )[0]
                for name in ailment_names
            ]
            recipe.ailments.set(recipe_ailments)

            seen_recipe_ingredients = []
            for order, (pinyin_name, amount, role, tcm_importance) in enumerate(
                ingredient_rows, start=1
            ):
                herb = Herb.objects.filter(pinyin_name=pinyin_name).first()
                lookup = {"recipe": recipe, "herb": herb}
                defaults = {
                    "name": "",
                    "amount": amount,
                    "role": role,
                    "tcm_importance": tcm_importance,
                    "order": order,
                }
                if herb is None:
                    lookup = {"recipe": recipe, "name": pinyin_name}
                    defaults["herb"] = None
                    defaults["name"] = pinyin_name
                ingredient, _ = FoodRecipeIngredient.objects.update_or_create(
                    **lookup,
                    defaults=defaults,
                )
                seen_recipe_ingredients.append(ingredient.pk)
            recipe.recipe_ingredients.exclude(pk__in=seen_recipe_ingredients).delete()

            seen_recipe_steps = []
            for order, instruction in enumerate(step_rows, start=1):
                FoodRecipeStep.objects.update_or_create(
                    recipe=recipe,
                    order=order,
                    defaults={"instruction": instruction},
                )
                seen_recipe_steps.append(order)
            recipe.steps.exclude(order__in=seen_recipe_steps).delete()
            recipes_created_or_updated += 1

        self.stdout.write(
            self.style.SUCCESS(
                f"Seeded {created_or_updated} herb records and "
                f"{formulas_created_or_updated} formula records and "
                f"{recipes_created_or_updated} recipe records."
            )
        )
